

DROP TABLE IF EXISTS `TIMEZONE`;
CREATE TABLE `TIMEZONE` (
   ID BIGINT NOT NULL AUTO_INCREMENT,
  `COUNTRY_CODE` varchar(2)  DEFAULT NULL,
  `TIMEZONE_ID` varchar(255)  DEFAULT NULL,
  `GMTOFFSET` float DEFAULT NULL,
  `DSTOFFSET` float DEFAULT NULL,
  `RAWOFFSET` float DEFAULT NULL,
  PRIMARY KEY (`ID`) 
);

CALL AlterTableAddColumn ('ORG_LOCATIONS','TIMEZONE_ID','BIGINT NULL AFTER `PRIMARY_CONTACT_USER_ID`');
ALTER TABLE `ORG_LOCATIONS` ADD FOREIGN KEY FK1_TIMEZONE (TIMEZONE_ID) REFERENCES TIMEZONE(ID);



